class TestPluginIntegration:
    """End-to-end integration tests combining all components"""

    def test_full_plugin_workflow(self, sample_config):
        """Verify complete plugin lifecycle: instantiate -> run -> findings"""

        class RealisticPlugin(ScannerPlugin):
            @property
            def plugin_id(self) -> str:
                return "realistic_plugin"

            async def run(self, target: str) -> List[Finding]:
                findings = []
                if target.startswith("192.168."):
                    findings.append(Finding(
                        plugin_id=self.plugin_id,
                        severity=Severity.MEDIUM,
                        title="Internal IP Detected",
                        description=f"Target {target} is on private network",
                        evidence={"ip": target, "is_private": True},
                        remediation="Ensure internal IPs are not exposed",
                        metadata={"network": "private"}
                    ))
                return findings

        plugin = RealisticPlugin(sample_config)

        # Test with private IP
        findings = asyncio.run(plugin.run("192.168.1.100"))
        assert len(findings) == 1
        finding = findings[0]
        assert finding.plugin_id == "realistic_plugin"
        assert finding.severity == Severity.MEDIUM
        assert finding.metadata["network"] == "private"

        # Test with public IP
        findings = asyncio.run(plugin.run("8.8.8.8"))
        assert len(findings) == 0

    def test_finding_sorting_by_severity(self, sample_config):
        """Verify findings can be sorted by severity"""

        class MultiFindingPlugin(ScannerPlugin):
            @property
            def plugin_id(self) -> str:
                return "multi"

            async def run(self, target: str) -> List[Finding]:
                return [
                    Finding(
                        plugin_id=self.plugin_id,
                        severity=Severity.LOW,
                        title="Low Issue",
                        description="Low severity finding",
                        evidence=None,
                        remediation="Fix low issue"
                    ),
                    Finding(
                        plugin_id=self.plugin_id,
                        severity=Severity.CRITICAL,
                        title="Critical Issue",
                        description="Critical severity finding",
                        evidence=None,
                        remediation="Fix critical issue"
                    ),
                    Finding(
                        plugin_id=self.plugin_id,
                        severity=Severity.HIGH,
                        title="High Issue",
                        description="High severity finding",
                        evidence=None,
                        remediation="Fix high issue"
                    )
                ]

        plugin = MultiFindingPlugin(sample_config)
        findings = asyncio.run(plugin.run("example.com"))

        # Sort by severity descending
        sorted_findings = sorted(findings, key=lambda f: f.severity.value, reverse=True)
        assert sorted_findings[0].severity == Severity.CRITICAL
        assert sorted_findings[1].severity == Severity.HIGH
        assert sorted_findings[2].severity == Severity.LOW

    def test_finding_filtering_by_plugin_id(self, sample_config):
        """Verify findings can be filtered by plugin_id"""

        class MultiPlugin(ScannerPlugin):
            @property
            def plugin_id(self) -> str:
                return "filter_test"

            async def run(self, target: str) -> List[Finding]:
                return [
                    Finding(
                        plugin_id=self.plugin_id,
                        severity=Severity.INFO,
                        title=f"Finding {i}",
                        description=f"Description {i}",
                        evidence=i,
                        remediation="Fix"
                    )
                    for i in range(5)
                ]

        plugin = MultiPlugin(sample_config)
        findings = asyncio.run(plugin.run("example.com"))

        # Filter by plugin_id
        filtered = [f for f in findings if f.plugin_id == "filter_test"]
        assert len(filtered) == 5

        # Filter by severity
        info_findings = [f for f in findings if f.severity == Severity.INFO]
        assert len(info_findings) == 5

