class TestPerformance:
    """Performance and stress testing"""

    def test_bulk_finding_creation(self, sample_finding_data):
        """Verify bulk Finding creation performance"""
        findings = []
        for i in range(10000):
            finding = Finding(**{
                **sample_finding_data,
                "plugin_id": f"plugin_{i}",
                "title": f"Finding {i}"
            })
            findings.append(finding)

        assert len(findings) == 10000
        assert findings[9999].plugin_id == "plugin_9999"

    def test_concurrent_plugin_execution(self, sample_config):
        """Verify concurrent async plugin execution"""

        class ConcretePlugin(ScannerPlugin):
            @property
            def plugin_id(self) -> str:
                return "test"

            async def run(self, target: str) -> List[Finding]:
                await asyncio.sleep(0.001)  # Simulate work
                return [Finding(
                    plugin_id=self.plugin_id,
                    severity=Severity.INFO,
                    title=f"Finding for {target}",
                    description="Test",
                    evidence=target,
                    remediation="None"
                )]

        plugin = ConcretePlugin(sample_config)

        async def run_concurrent():
            targets = [f"host_{i}.example.com" for i in range(100)]
            tasks = [plugin.run(target) for target in targets]
            results = await asyncio.gather(*tasks)
            return results

        results = asyncio.run(run_concurrent())
        assert len(results) == 100
        assert all(len(r) == 1 for r in results)

